# -- audit -------------------------------------------------------------
@staticmethod
def _audit_canonical(event):
    """Serialize *event* deterministically for hashing and storage."""
    return json.dumps(event, sort_keys=True,
                      separators=(",", ":")).encode("utf-8")

@classmethod
def _audit_hash(cls, event):
    """Return the chain hash of *event* (every field except ``hash``)."""
    payload = {name: value for name, value in event.items()
               if name != "hash"}
    return hashlib.sha256(cls._audit_canonical(payload)).hexdigest()

@staticmethod
def _parse_audit_line(line):
    """Parse and validate one audit log line or raise ``audit corrupted``."""
    try:
        event = json.loads(line.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        raise ObjectStoreError("audit corrupted")
    if not isinstance(event, dict):
        raise ObjectStoreError("audit corrupted")
    seq = event.get("seq")
    if isinstance(seq, bool) or not isinstance(seq, int) or seq < 1:
        raise ObjectStoreError("audit corrupted")
    tenant = event.get("tenant")
    if not isinstance(tenant, str) or _TENANT_RE.match(tenant) is None:
        raise ObjectStoreError("audit corrupted")
    if not isinstance(event.get("timestamp"), str):
        raise ObjectStoreError("audit corrupted")
    if not isinstance(event.get("operation"), str):
        raise ObjectStoreError("audit corrupted")
    if event.get("result") not in ("ok", "error"):
        raise ObjectStoreError("audit corrupted")
    if "prev_hash" not in event:
        raise ObjectStoreError("audit corrupted")
    prev_hash = event["prev_hash"]
    if prev_hash is not None and not _is_sha256(prev_hash):
        raise ObjectStoreError("audit corrupted")
    if not _is_sha256(event.get("hash")):
        raise ObjectStoreError("audit corrupted")
    for name in ("key", "session", "version", "error"):
        value = event.get(name)
        if value is not None and not isinstance(value, str):
            raise ObjectStoreError("audit corrupted")
    sha256 = event.get("sha256")
    if sha256 is not None and not _is_sha256(sha256):
        raise ObjectStoreError("audit corrupted")
    size = event.get("size")
    if size is not None and (isinstance(size, bool)
                             or not isinstance(size, int) or size < 0):
        raise ObjectStoreError("audit corrupted")
    return event

def _load_audit(self):
    """Load the audit log as (per-tenant seqs, heads, events).

    A missing log opens as empty. A trailing incomplete record (a crash
    mid-append) is discarded and truncated away; any other format error,
    a sequence gap or a hash-chain mismatch raises
    ``ObjectStoreError("audit corrupted")``.
    """
    seqs, heads, events = {}, {}, {}
    try:
        with open(self.audit_path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return seqs, heads, events
    except OSError:
        raise ObjectStoreError("audit io error")
    lines = raw.split(b"\n")
    trailing = lines.pop()
    for line in lines:
        event = self._parse_audit_line(line)
        tenant = event["tenant"]
        if event["seq"] != seqs.get(tenant, 0) + 1 \
                or event["prev_hash"] != heads.get(tenant) \
                or event["hash"] != self._audit_hash(event):
            raise ObjectStoreError("audit corrupted")
        seqs[tenant] = event["seq"]
        heads[tenant] = event["hash"]
        events.setdefault(tenant, []).append(event)
    if trailing:
        offset = sum(len(line) + 1 for line in lines)
        try:
            with open(self.audit_path, "r+b") as handle:
                handle.truncate(offset)
        except OSError:
            raise ObjectStoreError("audit io error")
    return seqs, heads, events

def _audit_event(self, tenant, operation, key=None, session=None,
                 version=None, result="ok", sha256=None, size=None,
                 error=None):
    """Append one event to *tenant*'s audit chain; caller holds the lock.

    Content, request bodies and secrets are never recorded. A failed
    write or flush is ``ObjectStoreError("audit io error")`` and leaves
    the chain untouched.
    """
    event = {"seq": self._audit_seqs.get(tenant, 0) + 1,
             "timestamp": datetime.now(timezone.utc).isoformat(),
             "tenant": tenant, "operation": operation, "result": result}
    if key is not None:
        event["key"] = key
    if session is not None:
        event["session"] = session
    if version is not None:
        event["version"] = version
    if sha256 is not None:
        event["sha256"] = sha256
    if size is not None:
        event["size"] = size
    if error is not None:
        event["error"] = error
    event["prev_hash"] = self._audit_heads.get(tenant)
    event["hash"] = self._audit_hash(event)
    line = self._audit_canonical(event) + b"\n"
    try:
        with open(self.audit_path, "ab") as handle:
            handle.write(line)
            handle.flush()
            os.fsync(handle.fileno())
    except OSError:
        raise ObjectStoreError("audit io error")
    self._audit_seqs[tenant] = event["seq"]
    self._audit_heads[tenant] = event["hash"]
    self._audit_events.setdefault(tenant, []).append(event)

def _audit_ok(self, tenant, operation, **fields):
    """Record a successful *operation* for *tenant*."""
    with self._lock:
        self._audit_event(tenant, operation, result="ok", **fields)

def _audit_error(self, tenant, operation, exc, **target):
    """Record a failed *operation*; an audit I/O failure wins over *exc*."""
    fields = {name: value for name, value in target.items()
              if isinstance(value, str)}
    with self._lock:
        self._audit_event(tenant, operation, result="error",
                          error=str(exc), **fields)

def _audit_snapshot(self, tenant):
    """Capture *tenant*'s mutable state for an audit-failure rollback."""
    snapshot = {}
    for name in ("_objects", "_timestamps", "_versions", "_versioning",
                 "_retention", "_quota", "_lifecycle", "_access",
                 "_rate_limit"):
        value = getattr(self, name).get(tenant, _MISSING)
        if value is _MISSING:
            continue
        if isinstance(value, dict):
            value = {key: (list(item) if isinstance(item, list)
                           else dict(item) if isinstance(item, dict)
                           else item)
                     for key, item in value.items()}
        snapshot[name] = value
    snapshot["_upload_records"] = {
        session_id: dict(record)
        for session_id, record in self._upload_records.items()
        if record["tenant"] == tenant}
    snapshot["_uploads"] = {
        session_id: dict(session)
        for session_id, session in self._uploads.items()
        if session["tenant"] == tenant}
    return snapshot

def _audit_restore(self, tenant, snapshot):
    """Undo a write with *snapshot* after its audit append failed."""
    for name in ("_objects", "_timestamps", "_versions", "_versioning",
                 "_retention", "_quota", "_lifecycle", "_access",
                 "_rate_limit"):
        mapping = getattr(self, name)
        if name in snapshot:
            mapping[tenant] = snapshot[name]
        else:
            mapping.pop(tenant, None)
    for session_id in [session_id for session_id, record
                       in self._upload_records.items()
                       if record["tenant"] == tenant]:
        del self._upload_records[session_id]
    self._upload_records.update(snapshot["_upload_records"])
    for session_id in [session_id for session_id, session
                       in self._uploads.items()
                       if session["tenant"] == tenant]:
        del self._uploads[session_id]
    self._uploads.update(snapshot["_uploads"])
    self._save_index()

def _audit_commit(self, tenant, snapshot, operation, **fields):
    """Record a successful write, rolling *snapshot* back on audit failure."""
    try:
        self._audit_ok(tenant, operation, **fields)
    except ObjectStoreError:
        with self._lock:
            try:
                self._audit_restore(tenant, snapshot)
            except OSError:
                pass
        raise

@staticmethod
def _check_audit_query(after, limit):
    """Validate the shared audit query parameters."""
    if after is not None and (isinstance(after, bool)
                              or not isinstance(after, int) or after < 0):
        raise ObjectStoreError("invalid audit query")
    if isinstance(limit, bool) or not isinstance(limit, int) \
            or not 1 <= limit <= MAX_LIMIT:
        raise ObjectStoreError("invalid audit query")

def list_audit_events(self, after=None, limit=DEFAULT_LIMIT,
                      tenant=DEFAULT_TENANT):
    """Return ``{"items": [...], "next_after": <int|null>}`` for one page.

    Only *tenant*'s own events are listed, in ascending ``seq`` order;
    *after* is an exclusive non-negative integer sequence cursor and
    *limit* bounds the page at 1 to 1000 events. A tenant without
    events yields an empty page. Querying records no audit event
    itself, and any parameter problem is
    ``ObjectStoreError("invalid audit query")``.
    """
    try:
        self._check_tenant(tenant)
    except ObjectStoreError:
        raise ObjectStoreError("invalid audit query")
    self._check_audit_query(after, limit)
    with self._lock:
        events = self._audit_events.get(tenant, [])
        cursor = after or 0
        remaining = [event for event in events if event["seq"] > cursor]
        page = remaining[:limit]
        return {"items": [dict(event) for event in page],
                "next_after": page[-1]["seq"]
