def _load_audit(self):
    """Load the audit log as (per-tenant seqs, heads, events).

    A missing log opens as empty. A trailing incomplete record (a crash
    mid-append) is discarded and truncated away; any other format error,
    a sequence gap or a hash-chain mismatch raises
    ``ObjectStoreError("audit corrupted")``.
    """
    seqs, heads, events = {}, {}, {}
    try:
        with open(self.audit_path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return seqs, heads, events
    except OSError:
        raise ObjectStoreError("audit io error")
    lines = raw.split(b"\n")
